      glossary: { eyebrow: 'Course vocabulary', title: 'Glossary', openDefinition: 'Open definition of {{term}}', terms: {
        differenceQuotient: { term: 'Difference quotient', definition: 'The ratio between the change in a function and the change h in its variable. The derivative arises from its limit.' },
        secant: { term: 'Secant line', definition: 'A line through two points of a graph. As the points move closer, secants may tend to the tangent.' },
        tangent: { term: 'Tangent line', definition: 'A line with the same local direction as the graph at a point; its slope is the derivative.' },
        differentiability: { term: 'Differentiability', definition: 'The existence of a finite derivative at a point, with the same limit from the left and right.' },
        prosthaphaeresis: { term: 'Prosthaphaeresis', definition: 'A trigonometric identity that turns sums or differences of sines and cosines into products.' },
        operatorNotation: { term: 'Operator notation', definition: 'The notation Df, which treats differentiation as an operation applied to the function f.' },
        curvature: { term: 'Curvature', definition: 'A geometric measure of how quickly a curve changes direction. It adds information beyond the sign of f″.' },
        osculatingCircle: { term: 'Osculating circle', definition: 'A circle that locally approximates the position, direction and curvature of a curve.' },
        maclaurin: { term: 'Maclaurin', definition: 'The Taylor polynomial centered at x₀=0, named after Colin Maclaurin.' },
        adequality: { term: 'Adequality', definition: 'A historical method for finding tangents and extrema, developed by Fermat before infinitesimal calculus.' },
        darboux: { term: 'Darboux', definition: 'The theorem stating that a derivative takes every intermediate value even when it is not continuous.' },
        cauchy: { term: 'Cauchy', definition: 'The mathematician who made limits, continuity and the generalized mean value theorem rigorous.' },
      } },
