      course: { velocita: { title: 'Le problème : vitesse instantanée', short: 'Vitesse instantanée' }, geometria: { title: 'Géométrie de la dérivée', short: 'Géométrie' }, definizione: { title: 'Définition formelle', short: 'Définition formelle' }, derivabilita: { title: 'Dérivabilité et points singuliers', short: 'Dérivabilité' }, interpretazioni: { title: 'Interprétations et applications', short: 'Interprétations' }, warmup: { title: 'Révision et échauffement', short: 'Échauffement' }, fondamentali: { title: 'Dérivées fondamentales', short: 'Dérivées fondamentales' }, regole: { title: 'Règles de dérivation', short: 'Règles de dérivation' }, 'derivata-seconda': { title: 'Dérivée seconde', short: 'Dérivée seconde' }, taylor: { title: 'Série de Taylor', short: 'Taylor · facultatif' }, teoremi: { title: 'Annexe : théorèmes sur les dérivées', short: 'Théorèmes · annexe' } },
      overview: { eyebrow: 'Cours guidé · deux leçons de 2 heures', title: 'Dérivées :', titleAccent: 'de la limite à la maîtrise.', intro: 'Nous partons d’une question concrète — comment mesurer une vitesse à un instant précis ? — puis construisons la géométrie, la définition et les règles sans sauter d’étapes.', openSummary: 'Ouvrir la synthèse', resume: 'Reprendre la leçon', start: 'Commencer par le problème', coreRead: '{{read}}/{{total}} SECTIONS FONDAMENTALES LUES · {{optional}}/{{optionalTotal}} APPROFONDISSEMENTS', progress: 'PROGRESSION DU COURS', coreSections: 'sections fondamentales lues', verified: 'concepts vérifiés', mastered: 'classes maîtrisées', enrichment: 'approfondissements consultés', oneQuestion: 'Une question, trois réponses', what: 'Qu’est-ce que la dérivée ?', question: 'QUESTION {{number}}', unlock: 'La réponse apparaît après la lecture de « {{section}} ».', cards: { geometry: { q: 'Comment trouver une pente sur une courbe ?', label: 'GÉOMÉTRIQUE', title: 'Une pente', answer: 'C’est la pente de la tangente, obtenue comme limite des sécantes.' }, analytic: { q: 'Pourquoi une limite apparaît-elle ?', label: 'ANALYTIQUE', title: 'Une limite', answer: 'C’est la limite du taux d’accroissement lorsque l’incrément tend vers zéro sans l’atteindre.' }, application: { q: 'Que mesure-t-elle vraiment ?', label: 'APPLIQUÉE', title: 'Un taux instantané', answer: 'Elle mesure la vitesse de variation d’une grandeur, avec un signe et une unité précise.' } }, lesson1: { title: 'Le concept de dérivée', subtitle: 'Du mouvement à la définition formelle', duration: '2 heures', objective: 'Construire la dérivée comme objet géométrique, analytique et physique.' }, lesson2: { title: 'Règles, Taylor et théorèmes', subtitle: 'Des démonstrations à la maîtrise du calcul', duration: '2 heures + annexe', objective: 'Déduire les règles à partir des limites, les appliquer et explorer les principaux théorèmes par des figures et des cas pratiques.' }, break: 'PAUSE + FEUILLE §{{sheet}} · 10 MIN', associated: 'Ressources associées', train: 'S’entraîner et s’évaluer', material: { sheet1: 'Feuille §1', sheet1Body: 'Définition et sens géométrique · 25 min', sheet2: 'Feuille §2', sheet2Body: 'Règles de dérivation · 30 min', test: 'Évaluation finale', testBody: '4 problèmes · 30 points · 45 min', adaptive: 'Exercices adaptatifs', adaptiveBody: '27 exercices de difficulté progressive' }, source: 'Code source', sourceBody: 'Consultez le projet, la documentation et l’historique des modifications sur GitHub.', openRepo: 'Ouvrir le dépôt' },
      lesson: { optional: 'Facultatif', appendix: 'Annexe', content: {
        velocita: { title: 'Une vitesse à un seul instant', lead: 'Avant la formule vient le problème : la vitesse moyenne correspond à un intervalle de temps, mais comment exprimer la vitesse à un instant sans durée ?' },
        geometria: { title: 'La sécante devient tangente', lead: 'La dérivée naît géométriquement en rapprochant deux points du graphe. Déplacez h et observez la pente de la sécante converger vers celle de la tangente.' },
        definizione: { title: 'La définition formelle', lead: 'Donnons maintenant une forme précise à l’intuition géométrique et physique. La dérivée existe lorsque le taux d’accroissement tend vers une valeur finie.' },
        derivabilita: { title: 'Continue ne signifie pas dérivable', lead: 'Une fonction dérivable est toujours continue. La réciproque peut échouer : un graphe peut rester continu tout en ayant un angle ou une tangente verticale.' },
        interpretazioni: { title: 'Trois façons de dire « dérivée »', lead: 'Le même objet mathématique décrit une pente, une limite et un taux de variation. Passer d’une lecture à l’autre est le véritable objectif de la leçon.' },
        warmup: { title: 'Trois questions pour repartir', lead: 'Avant de construire les règles de calcul, retrouvons les idées de la première leçon. Répondez oralement ou sur papier, puis ouvrez la correction.' },
        fondamentali: { title: 'Construisons le tableau ensemble', lead: 'La colonne centrale est la plus importante : retenez l’idée qui produit chaque formule afin de pouvoir la reconstruire.' },
        regole: { title: 'Quatre règles, quatre idées', lead: 'Pour chaque règle, nous relions la formule, sa démonstration par les limites et sa lecture verbale. Elle est prête à l’emploi seulement quand son origine est comprise.' },
        'derivata-seconda': { title: 'La dérivée de la dérivée', lead: 'f″ mesure la variation de la pente. Sur le graphe, elle décrit la concavité ; dans le mouvement, l’accélération.' },
        taylor: { title: 'L’ADN local d’une fonction', lead: 'Taylor répond à une question concrète : près d’un point choisi, peut-on remplacer une fonction difficile par un polynôme plus simple qui lui ressemble beaucoup ?' },
        teoremi: { title: 'Les théorèmes qui font travailler la dérivée', lead: 'Ce n’est pas encore une étude complète de fonction, mais une boîte à outils. Chaque théorème part d’une figure, répond à une question concrète et précise ses conditions.' },
      }, sectionRead: 'Section lue', didRead: 'Avez-vous lu cette section ?', readNotice: 'La lecture est enregistrée, mais ne vaut pas maîtrise vérifiée par les exercices.', read: 'Lue', markRead: 'Marquer comme lue', then: 'puis {{section}}', goSheet1: 'Aller à la feuille §1', goSheet2: 'Aller à la feuille §2' },
      adaptive: { eyebrow: 'Entraînement adaptatif', title: 'De la leçon', titleAccent: 'à la maîtrise.', intro: 'Les exercices sont organisés par prérequis et difficulté. Les notions à consolider reviennent d’abord, tandis que de nouvelles classes se débloquent avec vos progrès.', continue: 'Continuer les exercices', start: 'Commencer les exercices', completed: 'exercices terminés', firstTry: 'réussis du premier coup', proofs: 'démonstrations lues', classes: 'Classes de problèmes', yourPath: 'Votre parcours', unlockHint: 'Terminez une classe pour débloquer les concepts qui en dépendent.', exerciseCount: '{{count}} EXERCICES · {{points}} PTS', locked: 'Terminez d’abord : {{classes}}', loading: 'Préparation du parcours…', loadError: 'Impossible de charger les exercices : {{error}}', statusMastered: '✓ MAÎTRISÉE', statusRecovery: '↻ À REVOIR', statusProgress: '● EN COURS', statusStart: 'COMMENCER ICI →', statusAvailable: 'DISPONIBLE →', statusLocked: '🔒 VERROUILLÉE DANS LE PARCOURS', consult: 'Consulter quand même' },
