      glossary: { eyebrow: 'Vocabulaire du cours', title: 'Glossaire', openDefinition: 'Ouvrir la définition de {{term}}', terms: {
        differenceQuotient: { term: 'Taux d’accroissement', definition: 'Rapport entre la variation d’une fonction et la variation h de sa variable. La dérivée naît de sa limite.' },
        secant: { term: 'Sécante', definition: 'Droite passant par deux points du graphe. Lorsque les points se rapprochent, les sécantes peuvent tendre vers la tangente.' },
        tangent: { term: 'Tangente', definition: 'Droite ayant la même direction locale que le graphe en un point ; sa pente est la dérivée.' },
        differentiability: { term: 'Dérivabilité', definition: 'Existence d’une dérivée finie au point, avec la même limite à gauche et à droite.' },
        prosthaphaeresis: { term: 'Prostaphérèse', definition: 'Identité trigonométrique transformant des sommes ou différences de sinus et cosinus en produits.' },
        operatorNotation: { term: 'Notation opératorielle', definition: 'Écriture Df qui considère la dérivation comme une opération appliquée à la fonction f.' },
        curvature: { term: 'Courbure', definition: 'Mesure géométrique de la vitesse à laquelle une courbe change de direction. Elle complète le seul signe de f″.' },
        osculatingCircle: { term: 'Cercle osculateur', definition: 'Cercle qui approxime localement la position, la direction et la courbure d’une courbe.' },
        maclaurin: { term: 'Maclaurin', definition: 'Cas du polynôme de Taylor centré en x₀=0, nommé d’après Colin Maclaurin.' },
        adequality: { term: 'Adégalité', definition: 'Méthode historique de recherche des tangentes et des extrema, développée par Fermat avant le calcul infinitésimal.' },
        darboux: { term: 'Darboux', definition: 'Théorème selon lequel une dérivée prend toutes les valeurs intermédiaires même lorsqu’elle n’est pas continue.' },
        cauchy: { term: 'Cauchy', definition: 'Mathématicien qui a rendu rigoureux les limites, la continuité et le théorème des accroissements finis généralisé.' },
      } },
