      glossary: { eyebrow: 'Kursbegriffe', title: 'Glossar', openDefinition: 'Definition von {{term}} öffnen', terms: {
        differenceQuotient: { term: 'Differenzenquotient', definition: 'Das Verhältnis zwischen der Änderung einer Funktion und der Änderung h ihrer Variablen. Die Ableitung entsteht aus seinem Grenzwert.' },
        secant: { term: 'Sekante', definition: 'Eine Gerade durch zwei Punkte des Graphen. Wenn die Punkte zusammenrücken, können die Sekanten gegen die Tangente streben.' },
        tangent: { term: 'Tangente', definition: 'Eine Gerade mit derselben lokalen Richtung wie der Graph im Punkt; ihre Steigung ist die Ableitung.' },
        differentiability: { term: 'Differenzierbarkeit', definition: 'Existenz einer endlichen Ableitung im Punkt mit demselben links- und rechtsseitigen Grenzwert.' },
        prosthaphaeresis: { term: 'Prosthaphaeresis', definition: 'Eine trigonometrische Identität, die Summen oder Differenzen von Sinus und Kosinus in Produkte umwandelt.' },
        operatorNotation: { term: 'Operatornotation', definition: 'Die Schreibweise Df, die das Differenzieren als eine auf die Funktion f angewandte Operation betrachtet.' },
        curvature: { term: 'Krümmung', definition: 'Ein geometrisches Maß dafür, wie schnell eine Kurve ihre Richtung ändert. Sie ergänzt das bloße Vorzeichen von f″.' },
        osculatingCircle: { term: 'Krümmungskreis', definition: 'Ein Kreis, der Position, Richtung und Krümmung einer Kurve lokal annähert.' },
        maclaurin: { term: 'Maclaurin', definition: 'Der Spezialfall des Taylorpolynoms mit Zentrum x₀=0, benannt nach Colin Maclaurin.' },
        adequality: { term: 'Adäqualität', definition: 'Eine historische Methode zum Finden von Tangenten und Extrema, die Fermat vor der Infinitesimalrechnung entwickelte.' },
        darboux: { term: 'Darboux', definition: 'Der Satz, dass eine Ableitung auch bei Unstetigkeit alle Zwischenwerte annimmt.' },
        cauchy: { term: 'Cauchy', definition: 'Der Mathematiker, der Grenzwerte, Stetigkeit und den verallgemeinerten Mittelwertsatz streng begründete.' },
      } },
